//! The full Phosphor regular catalog (1512 icons) with search tags, for the icon picker and for
//! channel icons, which are stored as a Phosphor name (`"game-controller"`). Generated by
//! `tools/gen_icons.py` into `part_N.rs`; the parts are sorted by name, so lookup is a binary search.
//! The curated constants in `icons::*` stay the app's own chrome; this is for user choice.

use rune::Icon;

mod part_0;
mod part_1;
mod part_2;
mod part_3;

/// One catalog entry: the icon (its `name` is the Phosphor name) and its search tags.
pub struct CatalogIcon {
    pub icon: Icon,
    pub tags: &'static [&'static str],
}

static PARTS: [&[CatalogIcon]; 4] = [&part_0::PART, &part_1::PART, &part_2::PART, &part_3::PART];

/// Every icon, in name order.
pub fn all() -> impl Iterator<Item = &'static CatalogIcon> {
    PARTS.iter().flat_map(|p| p.iter())
}

/// How many icons the catalog holds.
pub fn len() -> usize {
    PARTS.iter().map(|p| p.len()).sum()
}

/// The entry for a Phosphor name.
pub fn entry(name: &str) -> Option<&'static CatalogIcon> {
    let part = PARTS
        .iter()
        .find(|p| p.last().is_some_and(|l| l.icon.name >= name))?;
    part.binary_search_by(|c| c.icon.name.cmp(name))
        .ok()
        .map(|i| &part[i])
}

/// The icon for a Phosphor name, if there is one.
pub fn by_name(name: &str) -> Option<&'static Icon> {
    entry(name).map(|c| &c.icon)
}

impl CatalogIcon {
    /// Whether every word of `query` is a prefix of the name or a part of it, or appears in a tag.
    /// An empty query matches everything.
    pub fn matches(&self, query: &str) -> bool {
        let q = query.trim().to_lowercase();
        q.split_whitespace().all(|w| {
            let w = w.replace('-', " ");
            self.icon.name.replace('-', " ").contains(&w)
                || self.tags.iter().any(|t| t.to_lowercase().contains(&w))
        })
    }

    /// Ranks a match: exact name, then name prefix, then name contains, then tag only (lower first).
    fn rank(&self, query: &str) -> u8 {
        let q = query.trim().to_lowercase().replace(' ', "-");
        let n = self.icon.name;
        if n == q {
            0
        } else if n.starts_with(&q) {
            1
        } else if n.contains(&q) {
            2
        } else {
            3
        }
    }
}

/// The icons that match `query`, best first (ties in name order). An empty query is the whole
/// catalog in name order.
pub fn search(query: &str) -> Vec<&'static CatalogIcon> {
    let mut found: Vec<&CatalogIcon> = all().filter(|c| c.matches(query)).collect();
    if !query.trim().is_empty() {
        found.sort_by_key(|c| c.rank(query));
    }
    found
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_catalog_is_whole_sorted_and_unique() {
        assert!(len() >= 1500, "{} icons", len());
        let names: Vec<&str> = all().map(|c| c.icon.name).collect();
        assert!(
            names.windows(2).all(|w| w[0] < w[1]),
            "sorted, no duplicates"
        );
        assert!(all().all(|c| c.icon.view == 256.0 && !c.icon.body.is_empty()));
    }

    #[test]
    fn lookup_finds_every_icon_and_nothing_else() {
        for c in all() {
            assert_eq!(by_name(c.icon.name).map(|i| i.name), Some(c.icon.name));
        }
        assert!(by_name("game-controller").is_some());
        assert!(by_name("hash").is_some());
        assert!(by_name("no-such-icon").is_none());
        assert!(by_name("").is_none());
        assert!(by_name("zzzz").is_none());
    }

    #[test]
    fn search_reads_names_and_tags() {
        let names = |q: &str| search(q).iter().map(|c| c.icon.name).collect::<Vec<_>>();
        assert_eq!(names("game-controller")[0], "game-controller");
        assert_eq!(names("game controller")[0], "game-controller");
        assert!(names("xbox").contains(&"game-controller"), "by tag");
        assert!(names("GAME").iter().any(|n| n.starts_with("game-")));
        assert_eq!(search("").len(), len());
        assert!(search("qqqqxx").is_empty());
        // A name prefix outranks a tag-only hit.
        let heart = names("heart");
        assert_eq!(heart[0], "heart");
    }
}
